import type { Modifier, Selection, TokenSet } from '../model.ts';
import { defaultSelection } from '../resolve.ts';

export const GENERATED_NOTICE =
  'GENERATED by packages/design-system/build. Do not edit: change tokens/*.json and run `pnpm tokens:build`.';

/** Public name of a sys token in the TS targets: `sys.text.muted` → `text-muted`. */
export const sysName = (id: string): string => id.slice('sys.'.length).replaceAll('.', '-');

export const sysIds = (set: TokenSet, type: 'color' | 'dimension'): string[] =>
  [...set.base.values()].filter((d) => d.layer === 'sys' && d.type === type).map((d) => d.id);

export function modifierNamed(set: TokenSet, name: string): Modifier {
  const m = set.manifest.modifiers.find((mod) => mod.name === name);
  if (!m) throw new Error(`the TS targets expect a "${name}" modifier in modes.json`);
  return m;
}

/** One selection per context of `names`, the other modifiers at their default. */
export function matrix(set: TokenSet, names: string[]): Array<{ keys: string[]; sel: Selection }> {
  let out: Array<{ keys: string[]; sel: Selection }> = [{ keys: [], sel: defaultSelection(set) }];
  for (const name of names) {
    const m = modifierNamed(set, name);
    out = out.flatMap(({ keys, sel }) =>
      Object.keys(m.contexts).map((ctx) => ({ keys: [...keys, ctx], sel: { ...sel, [name]: ctx } })),
    );
  }
  return out;
}

/** Nests `leaf` values under their matrix keys: [[a, b], v] → { a: { b: v } }. */
export function nest<T>(entries: Array<{ keys: string[]; value: T }>): Record<string, unknown> {
  const root: Record<string, unknown> = {};
  for (const { keys, value } of entries) {
    let node = root;
    keys.slice(0, -1).forEach((k) => (node = (node[k] ??= {}) as Record<string, unknown>));
    node[keys[keys.length - 1]!] = value;
  }
  return root;
}

export const unionType = (values: string[]): string => values.map((v) => JSON.stringify(v)).join(' | ');

/** JSON with 2-space indent, short number arrays kept on one line. */
export function toSource(value: unknown): string {
  return JSON.stringify(value, null, 2).replace(/\[\s+([-\d.,\s]+?)\s+\]/g, (_, inner: string) =>
    `[${inner.split(',').map((s) => s.trim()).join(', ')}]`,
  );
}

export const px = (v: { value: number; unit: 'px' | 'rem' }): number => (v.unit === 'px' ? v.value : v.value * 16);
